L.HEADER_TIP_TITLE = "How the army is counted"
L.HEADER_TIP = "One member with the addon in each guild, elected by the addons, reports it on Olympus's hidden channel every few minutes: how many members, who is online, the Lord and Captains, where they are. Your addon keeps the latest report of each guild it heard, and the total is their sum. Reports older than 15 minutes turn grey and their online players leave the count; a guild not heard from for a day leaves the total."
L.HEADER_TIP_DIFFER = "There is no central server: each addon counts what it heard since its login. Your own guild is live from your roster, the others are a report a few minutes old, and a guild whose addon users logged off keeps its size in the total for a day on the clients that heard it. So two players' numbers are often a bit apart, and that is not a bug."
