-- 0.9.1: channel-owner
L.CHANNEL_OWNER_YOU = "WoW just made you the owner of Olympus's hidden channel (%s). It hands a channel to another member whenever its owner leaves: nothing is wrong, and Olympus never uses these powers. Please don't use /password, /ban, /ckick, /moderator or /owner on it: that cuts the addon off for everyone."
L.CHANNEL_MODERATOR_YOU = "WoW just made you a moderator of Olympus's hidden channel (%s). It hands these powers to another member when a channel's owner leaves: nothing is wrong, and Olympus never uses them. Please don't use /password, /ban, /ckick or /moderator on it: that cuts the addon off for everyone."
L.CHANNEL_LOCKED = "Someone locked Olympus's hidden channel (%s) with a password or a ban, so the census and the Olympus channels can't reach you for now. Olympus keeps trying and gets back in as soon as it is open again. If WoW asks you for a password for it, just press Cancel: Olympus never needs one from you."
-- 0.9.1: privacy
L.CHANNEL_PUBLIC = "Your guild set no realm key, so the channel is public: anyone can join it by name."
L.CHANNEL_SEALED = "Your guild sealed the channel with a realm key: anyone who holds the key can join it."
L.LOCATION_ASK = "|cffe6c35cOlympus: share your zone and layer?|r\n\nIf you share, the addon may announce on the Olympus channel your zone, your layer, your guild rank and your guild, with your name on each message (the game adds it): officers and one member in eight do, every 10 minutes and when their layer changes. Your guild's census then names your zone if you lead your guild or are an officer, and counts members per zone when your addon is the one sending it.\n\nEveryone on the Olympus channel receives it. %s\n\nKeep it private and none of that is sent. Asking to hop to a layer still sends the zone you are in and the layer you want.\n\nChange it any time with /oly location on or /oly location off."
L.LOCATION_SHARE = "Share"
L.LOCATION_KEEP = "Keep private"
L.LOCATION_ON = "You share your zone and layer on the Olympus channel. /oly location off stops it."
L.LOCATION_OFF = "Your zone and layer stay private: the addon sends neither. /oly location on shares them."
L.HELP_LOCATION = "  /oly location on | off - share (or not) your zone and layer on the Olympus channel"
L.HOP_PRIVATE_HINT = "This ask told the Olympus channel the zone you are in and the layer you want; your own layer stays private. Layers are only known from the members who share theirs: the more share, the better hopping works (/oly location on)."
L.CHAN_WARN_ASK = "|cffe6c35c[%s] is not private.|r\n\nEvery addon on the Olympus channel receives the text of [Olympus], [Captains] and [Lords] alike and only chooses which lines to show you, so anyone on the channel can read all three with a script. %s\n\nNever write passwords or secrets there. Send your line? (Asked once per channel.)"
L.CHAN_WARN_NOT_SENT = "Your line was not sent."
L.THRONE_LOCATION_LAYER = "Your layer is announced with it, so the army can ask to join you there."
