-- 1.1.5: the version letters (Letters.lua), from the dev who makes the addon (no name: the author's call)
L.HELP_LETTERS = "  /oly letters [version] - the version letters: one for each update, newest first (or that version's)"
L.LETTERS_TITLE = "Letters from the dev"
L.LETTERS_INTRO = "One letter for each update, newest first."
L.LETTERS_BTN = "Version letters"
L.LETTERS_ALL = "All letters"
L.LETTERS_CLOSE = "Close"
L.LETTERS_CURRENT = "this version"
L.LETTERS_ROW = "%s  -  %s"
L.LETTER_TITLE = "Olympus %s"
L.LETTER_SIGNED = "The Olympus dev"
L.LETTER_MARK_STAR = "Star:" -- (a mark this client has no art for, in words)
L.LETTER_MARK_GOLD = "Gold dragon:"
L.LETTER_MARK_SILVER = "Silver dragon:"
L.LETTER_MARK_BRONZE = "Bronze dragon:"
L.LETTER_1_2_0_TITLE = "The Watch, crafting requests and the King's arrow"
L.LETTER_1_2_0 = "Version 1.2.0.\n\nNew\n- The Watch: your guild's own moderation desk for its officers. Reports, cases and the Tabards live there now.\n- Crafting requests: ask for an item from the Crafters tab, a crafter takes it, the two of you settle it in private.\n- The King's arrow: while the King shares where he is, your minimap points to him.\n- Vox Populi keeps your last 30 questions, and a guild master can ask his own guild.\n- Guild treasuries: every guild bank shared with the King and the High Council, in one list with one search.\n- Bones against another player, for points, at a tavern or at a camp (drop one with /oly camp).\n- Duels and Bones are between the two players: no arbiter, nothing to wait for.\n- Duel points consider levels: beating a higher level is worth more, beating a much lower one little or nothing.\n- Find a player for a duel or Bones: by level (within 5 or 10 of yours) and by distance (your zone or your continent).\n\nAlso\n- Everything 1.1.5 brought stays: the borders, the marks in the game's chat, the gamepad check."
L.LETTER_1_1_5_TITLE = "Borders mean something now"
L.LETTER_1_1_5 = "Version 1.1.5. Short version: fewer shiny things.\n\nBorders\n- The old rank borders are gone: Lords gold, Captains silver, Raiders and Veterans bronze.\n- New ones are coming, from the arena and more, and you'll have to earn them. A border everybody has is worth nothing.\n- For now three stay: the King, gold wings. The High Council, silver wings. Guild masters, bronze wings.\n- They show on your party's portraits too, not just your target and focus.\n- Guild masters can name up to 10 centurions and one correspondent per department from the Guild tab: bronze without wings. The King and the High Council name the King's guild's 10.\n- Everybody else gets the star on their nameplate. Still Olympus, just no medal for logging in.\n\nWho is who in the game's chat\n- {star} an Olympus member. Shows in Trade, General, say, party, raid and whispers. Not in guild chat: your guild already knows who you are.\n- {gold} the King.\n- {silver} the High Council.\n- {bronze} guild masters and the people they name.\n- The dragons show in guild chat too. Olympus lines carry no mark.\n\nGamepad\n- With the gamepad UI on, Olympus stays out of Blizzard's player menus, the guild windows and the chat box. Typed /oly commands need mouse and keyboard.\n- The nameplate errors are gone.\n- Every release now passes an automatic gamepad check before it ships.\n\nAlso\n- Every Olympus window wears the same bronze frame. Only the main window keeps the logo.\n- The Treasury tab has its new order: balance and bank first, the early supporters folded at the end.\n- Crafters: Cooking, Cocina and Culinaria are one profession now.\n- Decrees open with the army's agenda.\n- \"Always invite\" covers the party or raid you lead.\n- Dues paid from a confirmed alt count for its main.\n- These letters. One per update. Missed one? The \"i\" on the Olympus window keeps them all."
L.LETTER_1_1_4_TITLE = "Crafters got their own tab"
L.LETTER_1_1_4 = "Version 1.1.4. Small update. Don't read into it.\n\n- Crafters have a tab of their own. Find who can make the thing, whisper them, done.\n- The side tabs keep one order when they run out of room. No more hide and seek with your buttons."
L.LETTER_1_1_3_TITLE = "No surprise /who"
L.LETTER_1_1_3 = "Version 1.1.3.\n\n- A normal click no longer starts a /who search behind your back.\n- The census and the player searches run from their own buttons, when you ask.\n- The game is picky about /who. Now so are we.\n\nThat's it. Go back to what you were doing."
L.LETTER_1_1_2_TITLE = "Right-click, ask, answer"
L.LETTER_1_1_2 = "Version 1.1.2. Fewer questions in chat. That's the dream.\n\n- Right-click a player to see their Olympus version. Behind? Ask them to update. No addon? Tell them about Olympus. You write the whisper, you send it.\n- Every page has a ? that says what it shows and why two players can see different numbers. One answer bank, so everybody gets the same answer.\n- Bug reports when the author asks for one.\n- Chattynator tabs work."
L.LETTER_1_1_1_TITLE = "The Chat tab"
L.LETTER_1_1_1 = "Version 1.1.1. You wanted to read the chat without it flying by. Now you can.\n\n- [Olympus], [Captains] and [Lords] live in the Olympus window now, on the Chat tab.\n- Search it, scroll back, write from the box at the bottom.\n- The gear holds the settings: mute a channel, pick a chat window, or add an Olympus tab to the game's chat."
L.LETTER_1_1_0_TITLE = "The big one"
L.LETTER_1_1_0 = "Version 1.1.0, the Fernmelder release. That's a lot. Click around. Nothing explodes.\n\n- The LFG board.\n- The King's week, with sign-ups.\n- A crafters' board and loot notes.\n- A sound switch for each alert.\n- Census search and marked rows.\n- A privacy page when you first open it, so you choose what you share.\n- The inactive list and mentors.\n- Net-off, block terms, alt links, the key rotation and a pinned line.\n- The treasury's extras and the weekly dues.\n- Spanish, French and German."
