-- 1.1 (b2-moderation): net-off of a character (Moderation.lua).
L.HELP_NETOFF = "  /oly netoff [guild] [name: reason] | /oly neton [guild] <name> - the King, his Steward, a Hand or a High Councillor: hide a character on every Olympus surface for the whole army, or take a guild off the Olympus network; neton puts it back (/oly netoff alone lists them). /oly netoff guild <name> in 30|60: reason - the same with notice: its members see a countdown first, and neton cancels it before then"
L.NETOFF_TITLE = "Hidden by the moderators"
L.NETOFF_TIP = "The King, his Steward, a Hand or a High Councillor hid these characters for everyone with the addon: their chat lines, decrees, layers and hop offers, Vox Populi, requests at court, the King's week (entries and signups), the Board's flags and camps and the crafters' board don't show, nor their elite border or nameplate mark, and neither do those of the characters their player linked as alts. Nobody is removed from a guild or demoted, and Blizzard's ignore list is not touched. /oly block is still yours alone. A modified addon can ignore this."
L.NETOFF_YOU = "The moderators hid you for everyone with the addon (reason: %s; by %s, %s): your Olympus chat lines and pinned line, decrees, layers and hop, Vox, requests at court, entries and signups on the King's week, flags and camps on the Board, listing on the crafter board, and your elite border and nameplate mark. Blizzard's chat and your guild are not touched. Ask a moderator if you think it is a mistake."
