	L.CHANNEL_OWNER_YOU = "O WoW acabou de te fazer dono do canal oculto do Olympus (%s). Ele passa o canal pra outro membro sempre que o dono sai: não tem nada de errado, e o Olympus nunca usa esses poderes. Por favor, não use /senha, /banir, /cexpulsar, /moderador ou /dono nele: isso desliga o addon pra todo mundo."
	L.CHANNEL_MODERATOR_YOU = "O WoW acabou de te fazer moderador do canal oculto do Olympus (%s). Ele passa esses poderes pra outro membro quando o dono de um canal sai: não tem nada de errado, e o Olympus nunca usa eles. Por favor, não use /senha, /banir, /cexpulsar ou /moderador nele: isso desliga o addon pra todo mundo."
	L.CHANNEL_LOCKED = "Alguém trancou o canal oculto do Olympus (%s) com senha ou ban, então o censo e os canais Olympus não chegam em você por enquanto. O Olympus continua tentando e volta assim que o canal abrir de novo. Se o WoW pedir uma senha pra ele, é só apertar Cancelar: o Olympus nunca precisa de uma senha sua."
	-- 0.9.1: privacy
	L.CHANNEL_PUBLIC = "Sua guilda não definiu uma chave de reino, então o canal é público: qualquer um pode entrar nele pelo nome."
	L.CHANNEL_SEALED = "Sua guilda selou o canal com uma chave de reino: qualquer um que tenha a chave pode entrar nele."
	L.LOCATION_ASK = "|cffe6c35cOlympus: compartilhar sua zona e seu layer?|r\n\nSe você compartilhar, o addon pode anunciar no canal Olympus sua zona, seu layer, seu rank na guilda e sua guilda, com seu nome em cada mensagem (o jogo coloca): os officers e um membro em cada oito anunciam, a cada 10 minutos e quando o layer muda. O censo da sua guilda passa a mostrar sua zona se você for o líder ou officer, e a contar os membros por zona quando é o seu addon que o envia.\n\nTodos no canal Olympus recebem isso. %s\n\nSe mantiver privado, nada disso é enviado. Pedir para pular de layer ainda envia a zona onde você está e o layer que você quer.\n\nMude quando quiser com /oly location on ou /oly location off."
	L.LOCATION_SHARE = "Compartilhar"
	L.LOCATION_KEEP = "Manter privado"
	L.LOCATION_ON = "Você compartilha sua zona e seu layer no canal Olympus. /oly location off para."
	L.LOCATION_OFF = "Sua zona e seu layer ficam privados: o addon não envia nenhum dos dois. /oly location on compartilha."
	L.HELP_LOCATION = "  /oly location on | off - compartilhar (ou não) sua zona e seu layer no canal Olympus"
	L.HOP_PRIVATE_HINT = "Este pedido contou ao canal Olympus a zona onde você está e o layer que você quer; seu próprio layer continua privado. Os layers só são conhecidos pelos membros que compartilham os deles: quanto mais compartilham, melhor o pulo funciona (/oly location on)."
	L.CHAN_WARN_ASK = "|cffe6c35c[%s] não é privado.|r\n\nTodo addon no canal Olympus recebe o texto de [Olympus], [Capitães] e [Lordes] do mesmo jeito e só escolhe quais linhas te mostrar, então qualquer um no canal pode ler os três com um script. %s\n\nNunca escreva senhas ou segredos ali. Enviar sua linha? (Perguntado uma vez por canal.)"
	L.CHAN_WARN_NOT_SENT = "Sua linha não foi enviada."
	L.THRONE_LOCATION_LAYER = "Seu layer é anunciado junto, para o exército poder pedir para entrar nele."
