	L.UNTABARDED_STOP = "Parar de mostrar a lista dos sem tabardo ao exército"
	L.UNTABARDED_TIP = "Só você vê quem a Inspeção Real encontrou sem as cores. Ligado, todo membro das Olympus vê a lista nos Tabards da The Watch: sem alerta, sem som, sem linha no chat. Desligado, ela sai da tela deles."
	L.UNTABARDED_ON = "O exército agora vê a lista dos sem tabardo (só nos Tabards da The Watch, em silêncio)."
