	-- 0.9.2: author
	L.ROLLCALL_ON = "As chamadas do autor são respondidas: versão do addon, cliente do jogo e estado do canal, nada sobre o seu personagem. /oly rollcall off recusa."
	L.ROLLCALL_OFF = "As chamadas e avisos de atualização do autor são recusados. /oly rollcall on volta a responder."
	L.HELP_ROLLCALL = "  /oly rollcall on|off - responder ou não às chamadas do autor (versão, cliente, estado do canal)"
	-- 0.9.3: treasurer
	L.TREASURER_ONLY = "Só um guardião do tesouro pode mudar isso."
	L.TREASURER_SHARE_ASK = "Você guarda um livro do tesouro de Olympus (como Tesoureiro, como Rei, ou como personagem nomeado pelo Rei). Compartilhar o seu livro (saldo, ouro e itens dados e quem deu, o ranking) e o banco da guilda quando você o abrir (ouro e itens)? O sim do Tesoureiro também envia os nomes de todos que doaram antes da 1.0 (os primeiros apoiadores, do livro da 0.9).\n\nO que o Rei mostra ao exército sai no canal Olympus, e todo cliente nele recebe, os nomes também. %s O resto vai por sussurro só ao Rei, ao Senescal dele (um personagem que o autor pode nomear para agir por ele) e aos guardiões do tesouro, nunca no canal. Mude quando quiser com /oly treasurer on ou off."
	L.TREASURER_SHARE_YES = "Compartilhar"
	L.TREASURER_SHARE_NO = "Manter privado"
	L.TREASURER_SHARE_ON = "Seu livro do tesouro e o banco da guilda estão compartilhados (o Rei e o Senescal dele veem; o exército só se o Rei permitir). /oly treasurer off retira."
	L.TREASURER_SHARE_OFF = "Seu livro do tesouro e o banco da guilda são só seus (retirados de toda tela; o seu addon repete isso a cada 5 minutos enquanto você joga, para quem estava offline). /oly treasurer on compartilha."
	L.HELP_TREASURER = "  /oly treasurer on|off - um guardião do tesouro compartilha ou não o livro dele e o banco da guilda"
	-- 0.9.3: inspection opt-out
	L.INSPECTION_OPT_ON = "Você participa da Inspeção Real do Rei quando seu addon cai na amostra: uma patrulha de 2 minutos nos jogadores ao seu redor, reportada a ele. /oly inspection off recusa."
	L.INSPECTION_OPT_OFF = "Você não participa das Inspeções Reais: ainda ouve o chamado do Rei, e nada é inspecionado nem reportado. /oly inspection on volta a participar."
	L.HELP_INSPECTION = "  /oly inspection on|off - participar ou não da Inspeção Real do Rei"
	L.HELP_BORDERS = "  /oly borders on | off - bordas de elite no seu alvo, no seu foco, no seu grupo e no seu próprio retrato (o Rei, o High Council, os mestres de guilda e quem eles indicam) e as marcas nas placas de identificação dos jogadores aliados, ou nenhuma"
	L.BORDERS_ON = "Bordas de elite ligadas no seu alvo, no seu foco e no seu próprio retrato: dourada com asas para o Rei, prateada com asas para o High Council, bronze com asas para os mestres das guildas Olympus e bronze sem asas para os centuriões e correspondentes que eles indicam. Com elas, uma marca à esquerda do nome nas placas de identificação dos jogadores aliados (/oly nameplates). /oly borders off esconde as duas."
	L.BORDERS_OFF = "Bordas de elite desligadas: nenhuma no seu alvo, no seu foco ou no seu próprio retrato, e nenhuma marca nas placas de identificação. /oly borders on mostra de novo."
	L.BORDERS_GAMEPAD = "Com a interface de gamepad elas ficam escondidas: lá o Olympus deixa em paz os quadros de unidade do jogo. Elas voltam com mouse e teclado."
	L.BORDERS_PREVIEW_ON = "Prévia de borda: %s em volta do seu próprio retrato, e no quadro do alvo quando você mira em si mesmo; a marca dela depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado. Só na sua tela: nada é enviado, e um /reload esquece. /oly borders test off encerra."
	L.BORDERS_PREVIEW_ON_NO_MARK = "Prévia de borda: %s em volta do seu próprio retrato, e no quadro do alvo quando você mira em si mesmo. As marcas nas placas de identificação estão desligadas, então nenhuma marca aparece com ela (/oly nameplates on mostra). Só na sua tela: nada é enviado, e um /reload esquece. /oly borders test off encerra."
	L.BORDERS_PREVIEW_ON_MEMBER = "Prévia de marca: member, a estrela do Olympus, depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado. As bordas não têm o nível member: nenhuma em volta do seu retrato. Só na sua tela: nada é enviado, e um /reload esquece. /oly borders test off encerra."
	L.BORDERS_PREVIEW_OFF = "Prévia de borda desligada: seu próprio retrato volta a mostrar a borda do seu cargo, se houver, e as placas de identificação as marcas de cada um."
	L.BORDERS_PREVIEW_HELP = "/oly borders test <borda> | off - uma borda em volta do seu próprio retrato e a marca dela nas placas de identificação, só na sua tela. Bordas: %s; member: só a estrela (uma marca, sem borda)."
	L.BORDERS_PREVIEW_WHEN_OFF = "As bordas de elite estão desligadas, então a prévia espera: /oly borders on mostra."
	L.BORDERS_PREVIEW_NOT_MEMBER = "As bordas só aparecem numa guilda Olympus: a prévia espera até você estar numa."
	L.BORDERS_PREVIEW_COMBAT = "Em combate: as bordas são montadas quando a luta acabar, e a prévia aparece então."
	L.BORDERS_PREVIEW_MISSING = "Este cliente não tem quadro nem arte para essa borda: nada para mostrar."
	L.BORDERS_PREVIEW_TITLE = "Prévia das bordas de elite"
	L.BORDERS_PREVIEW_NONE = "desligada"
	L.BORDERS_PREVIEW_NOW = "mostrando %s"
	L.BORDERS_PREVIEW_SHOWN = "à mostra"
	L.BORDERS_PREVIEW_TIP = "Mostra esta borda em volta do seu próprio retrato, e no quadro do alvo quando você mira em si mesmo, como quem a tem vê a própria, e a marca dela depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado. Só na sua tela: nada é enviado, e um /reload esquece. Clique de novo, ou digite /oly borders test off, para encerrar."
	L.BORDERS_PREVIEW_TIP_MEMBER = "Mostra a estrela de qualquer outro membro do Olympus depois do seu nome no seu quadro e na placa de identificação de todo jogador aliado (nenhuma borda a tem). Só na sua tela: nada é enviado, e um /reload esquece. Clique de novo, ou digite /oly borders test off, para encerrar."
	L.BORDERS_WHO_GOLD_ELITE = "dourada com asas: o Rei"
	L.BORDERS_WHO_TREASURER_DRAGON = "o dragão de joias: o Tesoureiro federal"
	L.BORDERS_WHO_SILVER_ELITE = "prateada com asas: o High Council"
	L.BORDERS_WHO_BRONZE_ELITE = "bronze com asas: mestres de guilda"
	L.BORDERS_WHO_MEMBER = "a estrela: qualquer outro membro (uma marca nas placas, sem borda)"
	L.HELP_NAMEPLATES = "  /oly nameplates on | off - uma marca à esquerda do nome nas placas de identificação dos jogadores aliados (o Rei dourada, o High Council prateada, os mestres de guilda bronze, qualquer outro membro de uma guilda Olympus uma estrela), ou nenhuma"
	L.NAMEPLATES_ON = "Marcas nas placas de identificação ligadas: à esquerda do nome dos jogadores aliados de guildas Olympus, a marca de elite dourada do jogo para o Rei, a prateada para o High Council, bronze para os mestres de guilda, e uma estrela para qualquer outro membro. As placas dos aliados aparecem com Shift+V. /oly nameplates off esconde as marcas."
	L.NAMEPLATES_OFF = "Marcas nas placas de identificação desligadas. /oly nameplates on mostra de novo."
	L.NAMEPLATES_BORDERS_OFF = "Marcas nas placas de identificação ligadas, mas escondidas junto com as bordas de elite: /oly borders on mostra as duas."
	L.NAMEPLATES_GAMEPAD = "Com a interface de gamepad elas ficam escondidas: lá o Olympus deixa em paz as placas de identificação do jogo. Elas voltam com mouse e teclado."
	L.NAMEPLATES_PREVIEW_WHEN_OFF = "As marcas nas placas de identificação estão desligadas, então a prévia da marca espera: /oly nameplates on mostra."
	-- 1.1.5: the High Council's marks in the game's own chat (Borders.lua)
	L.HELP_CHATMARKS = "  /oly chatmarks on | off - as marcas do Olympus antes dos nomes no chat do jogo (canais, dizer, grupo, raide, sussurros; no chat da guilda só os dragões): o Rei dourada, o High Council prateada, os mestres de guilda e quem eles indicam bronze, os membros uma estrela; ou nenhuma"
	L.CHATMARKS_ON = "Marcas no chat do jogo ligadas: antes do nome de um jogador do Olympus nos canais (Geral, Comércio...), dizer, gritar, emote, grupo, raide, instância e sussurros. O dragão dourado para o Rei, o prateado para o High Council (e depois o ícone que escolheram), o bronze para os mestres de guilda e os centuriões e correspondentes que eles indicam, a estrela para qualquer outro membro que o Olympus consegue conferir. O chat da guilda e o dos oficiais mostram só os dragões, nunca a estrela: a guilda já conhece os seus. /oly chatmarks off esconde."
	L.CHATMARKS_OFF = "Marcas no chat do jogo desligadas: nenhuma marca antes de nome nenhum lá. /oly chatmarks on mostra de novo."
	L.CHATMARKS_GAMEPAD = "Com a interface de gamepad elas ficam escondidas: lá o Olympus deixa em paz o chat do jogo. Elas voltam com mouse e teclado."
	L.CHATMARKS_NO_API = "Este cliente não deixa pôr marcas no chat do jogo: nenhuma marca lá."
	L.CHATMARKS_TEST_ON = "Prévia da marca no chat: a marca %s antes do seu próprio nome no chat do jogo. Só na sua tela: nada é enviado, e um /reload esquece. /oly chatmarks test off encerra."
	L.CHATMARKS_TEST_OFF = "Prévia da marca no chat desligada."
	L.CHATMARKS_TEST_HELP = "/oly chatmarks test [gold | silver | bronze | member | off] - essa marca antes do seu próprio nome no chat do jogo, só na sua tela."
	-- 1.1.5: as cartas das versões (Letters.lua), do dev que faz o addon (sem nome: decisão do autor)
	L.HELP_LETTERS = "  /oly letters [versão] - as cartas das versões: uma para cada atualização, da mais nova para a mais antiga (ou a daquela versão)"
	L.LETTERS_TITLE = "Cartas do dev"
	L.LETTERS_INTRO = "Uma carta para cada atualização, da mais nova para a mais antiga."
	L.LETTERS_BTN = "Cartas das versões"
	L.LETTERS_ALL = "Todas as cartas"
	L.LETTERS_CLOSE = "Fechar"
	L.LETTERS_CURRENT = "esta versão"
	L.LETTERS_ROW = "%s  -  %s"
	L.LETTER_TITLE = "Olympus %s"
	L.LETTER_SIGNED = "O dev do Olympus"
	L.LETTER_MARK_STAR = "Estrela:"
	L.LETTER_MARK_GOLD = "Dragão dourado:"
	L.LETTER_MARK_SILVER = "Dragão prateado:"
	L.LETTER_MARK_BRONZE = "Dragão de bronze:"
	L.LETTER_1_2_0_TITLE = "The Watch, os pedidos de artesão e a seta do Rei"
	L.LETTER_1_2_0 = "Versão 1.2.0.\n\nNovo\n- The Watch: a mesa de moderação da sua guilda, para os oficiais dela. Denúncias, casos e os Tabards ficam lá agora.\n- Pedidos de artesão: peça um item pela aba Artesãos, um artesão aceita, vocês dois acertam no privado.\n- A seta do Rei: enquanto o Rei compartilha onde está, o seu minimapa aponta para ele.\n- O Vox Populi guarda as suas últimas 30 perguntas, e um mestre de guilda pode perguntar à guilda dele.\n- Tesouros das guildas: todo banco de guilda compartilhado com o Rei e o High Council, numa lista só, com uma busca só.\n- Bones contra outro jogador, por pontos, numa taverna ou num acampamento (monte um com /oly camp).\n- Duelos e Bones são entre os dois jogadores: sem árbitro, nada a esperar.\n- Os pontos dos duelos consideram o nível: vencer um nível mais alto vale mais, vencer um muito mais baixo vale pouco ou nada.\n- Encontre um jogador para um duelo ou para o Bones: por nível (a até 5 ou 10 do seu) e por distância (sua zona ou seu continente).\n\nE mais\n- Tudo o que a 1.1.5 trouxe continua: as bordas, as marcas no chat do jogo, a checagem de gamepad."
	L.LETTER_1_1_5_TITLE = "Agora borda tem que valer"
	L.LETTER_1_1_5 = "Versão 1.1.5. Resumindo: menos coisa brilhando.\n\nBordas\n- As bordas de cargo antigas acabaram: Lordes dourada, Capitães prateada, Raiders e Veteranos bronze.\n- Bordas novas estão vindo, da arena e de outros lugares, e vão ter que ser conquistadas. Borda que todo mundo tem não vale nada.\n- Por enquanto ficam três: o Rei, asas douradas. O High Council, asas prateadas. Mestres de guilda, asas de bronze.\n- Agora aparecem também nos retratos do seu grupo, não só no alvo e no foco.\n- Mestres de guilda podem indicar até 10 centuriões e um correspondente por departamento da aba Guilda: bronze sem asas. O Rei e o High Council indicam os 10 da guilda do Rei.\n- O resto fica com a estrela na placa de identificação. Continua sendo Olympus, só não ganha medalha por fazer login.\n\nQuem é quem no chat do jogo\n- {star} um membro do Olympus. Aparece no Comércio, Geral, dizer, grupo, raide e sussurros. Não no chat da guilda: sua guilda já sabe quem você é.\n- {gold} o Rei.\n- {silver} o High Council.\n- {bronze} mestres de guilda e quem eles indicam.\n- Os dragões aparecem no chat da guilda também. Linhas do Olympus não levam marca.\n\nGamepad\n- Com a interface de gamepad ligada, o Olympus fica fora dos menus de jogador da Blizzard, das janelas da guilda e da caixa do chat. Comandos /oly digitados precisam de mouse e teclado.\n- Os erros das placas de identificação acabaram.\n- Toda versão agora passa por uma checagem automática de gamepad antes de sair.\n\nE mais\n- Toda janela do Olympus usa a mesma moldura de bronze. Só a janela principal fica com o logo.\n- A aba Tesouro tem a ordem nova: saldo e banco primeiro, os primeiros apoiadores recolhidos no fim.\n- Artesãos: Cooking, Cocina e Culinária agora são uma profissão só.\n- Os Decretos abrem com a agenda do exército.\n- O \"Always invite\" vale para o grupo ou raide que você lidera.\n- Taxas pagas por um alt confirmado contam para o main.\n- Estas cartas. Uma por atualização. Perdeu uma? O \"i\" da janela do Olympus guarda todas."
	L.LETTER_1_1_4_TITLE = "Artesãos ganharam aba própria"
	L.LETTER_1_1_4 = "Versão 1.1.4. Atualização pequena. Não procure significado.\n\n- Os artesãos têm uma aba só deles. Ache quem faz o item, sussurre, pronto.\n- As abas laterais mantêm uma ordem só quando falta espaço. Chega de esconde-esconde com os botões."
	L.LETTER_1_1_3_TITLE = "Nada de /who surpresa"
	L.LETTER_1_1_3 = "Versão 1.1.3.\n\n- Um clique comum não começa mais uma busca /who pelas suas costas.\n- O censo e as buscas de jogador rodam nos botões deles, quando você pede.\n- O jogo é chato com /who. Agora a gente também é.\n\nSó isso. Pode voltar ao que estava fazendo."
	L.LETTER_1_1_2_TITLE = "Botão direito, pergunta, resposta"
	L.LETTER_1_1_2 = "Versão 1.1.2. Menos pergunta no chat. Esse é o sonho.\n\n- Botão direito num jogador mostra a versão do Olympus dele. Atrasado? Peça para atualizar. Sem addon? Conte do Olympus. Você escreve o sussurro, você envia.\n- Toda página tem um ? que diz o que ela mostra e por que dois jogadores podem ver números diferentes. Um banco de respostas só, então todo mundo recebe a mesma.\n- Relatório de bug quando o autor pedir.\n- As abas do Chattynator funcionam."
	L.LETTER_1_1_1_TITLE = "A aba Chat"
	L.LETTER_1_1_1 = "Versão 1.1.1. Você queria ler o chat sem ele passar voando. Agora dá.\n\n- [Olympus], [Capitães] e [Lordes] agora moram na janela do Olympus, na aba Chat.\n- Busque, volte no histórico, escreva na caixa embaixo.\n- A engrenagem guarda as opções: silenciar um canal, escolher uma janela de chat, ou pôr uma aba Olympus no chat do jogo."
	L.LETTER_1_1_0_TITLE = "A grande"
	L.LETTER_1_1_0 = "Versão 1.1.0, a versão Fernmelder. É bastante coisa. Clique por aí. Nada explode.\n\n- O quadro de LFG.\n- A semana do Rei, com inscrições.\n- Um quadro de artesãos e notas de loot.\n- Um botão de som para cada alerta.\n- Busca no censo e linhas marcadas.\n- Uma página de privacidade na primeira abertura, para você escolher o que compartilha.\n- A lista de inativos e os mentores.\n- Net-off, termos bloqueados, vínculo de alts, a troca de chave e uma linha fixada.\n- Os extras do tesouro e as taxas semanais.\n- Espanhol, francês e alemão."
	-- 0.9.5: issue reporter
