-- 1.1 (Fern's #11): the first-open page of what this addon shares (Consent.lua), the Olympus
-- chats on or off, and the switches that stay off until answered.
---------------------------------------------------------------------------
L.CONSENT_TITLE = "Olympus: what this addon shares"
L.CONSENT_INTRO = "While you are in an Olympus guild, two things always go out. One member of your guild, elected by the addons, sends your guild's census on the Olympus channel: its size, online count, classes, levels and rank names, its leader and officers (name, online, days away, class, level) and its five highest-level members (name, level, class), online or not. And your addon says hello to your guild: its version, your realm, whether your channel is public or sealed and whether you share your zone. %s"
L.CONSENT_OPTIONAL = "Nothing below goes out, or shows, until you say Yes, and until you answer each one stays off, unless its line says a yes you gave before still stands, or that it is on until you say No."
L.CONSENT_FOOTER = "The window, the census and your own guild's roster work whatever you answer. Change any answer later: /oly privacy opens this page again."
L.CONSENT_DONE = "Done"
L.CONSENT_ACCEPT_ALL = "Accept all"
L.CONSENT_YES = "Yes"
L.CONSENT_NO = "No"
L.CONSENT_STATE_YES = "Yes"
L.CONSENT_STATE_NO = "No"
L.CONSENT_STATE_NONE = "Not answered: off"
L.CONSENT_STATE_LOCAL = "Local only"
L.CONSENT_STATE_SHARED = "Shared"
L.CONSENT_STATE_DERIVED = "Derived here"
L.CONSENT_STATE_HIDDEN = "Hidden"
L.CONSENT_STATE_UNKNOWN = "Unknown"
L.CONSENT_STATE_UNAVAILABLE = "Unavailable"
L.CONSENT_PROFILE_SECTION = "Profile"
L.CONSENT_ALL_SHARING = "All sharing"
L.CONSENT_PROFILE_TITLE = "Olympus: profile privacy"
L.CONSENT_PROFILE_INTRO = "This section separates facts kept on this client, facts received from other addons, facts derived here and facts you chose to share. It does not turn unavailable data into a guess."
L.CONSENT_PROFILE_OPTIONAL = "Only rows with Yes and No have a real sharing switch. Status-only rows describe what the addon can actually do; they cannot authorize a protocol that does not exist."
L.CONSENT_PROFILE_IDENTITY = "Profile: census identity"
L.CONSENT_PROFILE_IDENTITY_TEXT = "Name, guild, rank, level, class and online state come from facts already present in the census, roster, /who or this client. Opening a profile requests nothing new."
L.CONSENT_PROFILE_PRESENTATION = "Profile: arena presentation"
L.CONSENT_PROFILE_PRESENTATION_TEXT = "Your chosen arena frame, title, nickname, emblem and short history are presentation stored on this client. The Arena companion is optional; the normal profile does not load it."
L.CONSENT_LOCATION = "Your zone and layer"
L.CONSENT_LOCATION_TEXT = "Your zone, your layer, your guild rank and your guild, with your name, to everyone on the Olympus channel (officers and one member in eight announce them, every 10 minutes and when the layer changes), and your guild's members per zone in its census. Layer hops work better the more members share. (/oly location on|off)"
L.CONSENT_LAYERHELP = "Help others join your layer"
L.CONSENT_LAYERHELP_TEXT = "When someone asks for the layer you are on, your addon may whisper them alone that you are there, and then asks you whether to invite them (you click Invite). If they are discovering the King's layer while his crown is visible, an exact nameplate sighting may answer that active asker alone; two independent observers must agree. Nothing is broadcast just because you see him. (/oly layerhelp on|off)"
L.CONSENT_NEEDS_LOCATION = "Only while you share your zone and layer."
L.CONSENT_TREASURER = "Your book of the treasury (keepers)"
L.CONSENT_TREASURER_TEXT = "Your book (its balance, the gold and items given and who gave them, the ranking of donors) and the guild bank of <Olympus>, to everyone on the Olympus channel, every 5 minutes while you play. The addon shows them to the King and his Steward, and to the army only with the King's switches. (/oly treasurer on|off)"
L.CONSENT_TREASURER_EARLY = "As the Treasurer, your Yes also sends the names of everyone who gave before 1.0 (the early supporters, from 0.9's book): every client on the Olympus channel receives them, the names too."
L.CONSENT_TREASURER_OLD_YES = "Your yes of 0.9.3 still sends your book until you answer here."
L.CONSENT_INSPECTION = "The King's Royal Inspection"
L.CONSENT_INSPECTION_TEXT = "When the King, his Steward or a Hand calls one and your addon is in the sample, it inspects the Olympus players around you for 2 minutes, then whispers whoever called it alone: your guild, how many wore the guild tabard, another one or none, and up to 6 names of players caught without the colors. You get its raid warning either way. (/oly inspection on|off)"
L.CONSENT_ROLLCALL = "The author's roll call"
