L.CONSENT_CHAT_TEXT = "[Olympus], [Captains] and [Lords] (/ol, /olc, /oll), and the pinned line. Yes: other players' lines show here, and you can write; every line you write reaches everyone on the Olympus channel. No: this client neither sends nor shows them. (/oly chat on|off)"
L.CONSENT_TABARD_SELF_V2 = "Your own tabard report"
L.CONSENT_TABARD_SELF_V2_TEXT = "Your server-stamped character identity, Olympus guild, level and current tabard result (guild tabard, another, none, exempt below level 15, or incomplete) are whispered only to the exact King client authenticated in the last 10 minutes. At most every 10 minutes and when your tabard changes. Raw evidence is kept for up to 24 hours. No leaves it off; changing to No cancels every waiting report before delivery. A new data contract asks again."
L.CONSENT_TABARD_NEARBY_V2 = "Direct nearby tabard observations"
L.CONSENT_TABARD_NEARBY_V2_TEXT = "Only after an inspection your client already completed, it may whisper the exact King client authenticated in the last 10 minutes: that player's name, Olympus guild, level and tabard result, plus your server-stamped identity as the observer. The King client records when it arrived. It never starts a second inspection, relays another player's report, or broadcasts a subject's name to guild or Olympus channels. At most one result for the same player per minute; raw evidence is kept for up to 24 hours. No cancels every waiting report before delivery. A new data contract asks again."
L.UNTABARDED_PUBLISHED_EMPTY = "Published by the King: no entries"
L.VIEW_AS_TITLE = "View as"
L.VIEW_AS_TIP = "The author's local preview. My view: every tab, each showing what your own character may see. A role: the tabs and sections that role sees, labelled as a preview. It never changes your rank, your authority, the data you received or what a click may send."
