	L.CONSENT_STATE_LOCAL = "Só local"
	L.CONSENT_STATE_SHARED = "Compartilhado"
	L.CONSENT_STATE_DERIVED = "Derivado aqui"
	L.CONSENT_STATE_HIDDEN = "Oculto"
	L.CONSENT_STATE_UNKNOWN = "Desconhecido"
	L.CONSENT_STATE_UNAVAILABLE = "Indisponível"
	L.CONSENT_PROFILE_SECTION = "Perfil"
	L.CONSENT_ALL_SHARING = "Todo compartilhamento"
	L.CONSENT_PROFILE_TITLE = "Olympus: privacidade do perfil"
	L.CONSENT_PROFILE_INTRO = "Esta seção separa dados guardados neste cliente, dados recebidos de outros addons, dados derivados aqui e dados que você escolheu compartilhar. Ela não transforma dados indisponíveis em suposições."
	L.CONSENT_PROFILE_OPTIONAL = "Só as linhas com Sim e Não têm um controle real de compartilhamento. Linhas apenas de status descrevem o que o addon realmente consegue fazer; elas não autorizam um protocolo que não existe."
	L.CONSENT_PROFILE_IDENTITY = "Perfil: identidade do censo"
	L.CONSENT_PROFILE_IDENTITY_TEXT = "Nome, guilda, patente, nível, classe e estado online vêm de dados já presentes no censo, roster, /who ou neste cliente. Abrir um perfil não pede nada novo."
	L.CONSENT_PROFILE_PRESENTATION = "Perfil: apresentação da arena"
	L.CONSENT_PROFILE_PRESENTATION_TEXT = "A moldura, título, apelido, emblema e história curta que você escolheu para a arena são apresentação guardada neste cliente. O companion da Arena é opcional; o perfil normal não o carrega."
	L.CONSENT_LOCATION = "Sua zona e seu layer"
	L.CONSENT_LOCATION_TEXT = "Sua zona, seu layer, sua patente e sua guilda, com o seu nome, para todos no canal Olympus (os oficiais e um membro em cada oito anunciam, a cada 10 minutos e quando o layer muda), e os membros da sua guilda por zona no censo dela. O salto de layer funciona melhor quanto mais membros compartilham. (/oly location on|off)"
	L.CONSENT_LAYERHELP = "Ajudar outros a entrar no seu layer"
	L.CONSENT_LAYERHELP_TEXT = "Quando alguém pede o layer em que você está, o seu addon pode sussurrar só para essa pessoa que você está lá, e depois pergunta se você convida (você clica em Convidar). Se a pessoa estiver descobrindo o layer do King enquanto a coroa dele estiver visível, um avistamento da nameplate exata pode responder somente a esse pedido ativo; dois observadores independentes precisam concordar. Nada é transmitido só porque você o viu. (/oly layerhelp on|off)"
	L.CONSENT_NEEDS_LOCATION = "Só enquanto você compartilha a sua zona e o seu layer."
	L.CONSENT_TREASURER = "Seu livro do tesouro (guardiões)"
	L.CONSENT_TREASURER_TEXT = "O seu livro (saldo, o ouro e os itens doados e quem doou, o ranking de doadores) e o banco da guilda <Olympus>, para todos no canal Olympus, a cada 5 minutos enquanto você joga. O addon mostra ao Rei e ao Senescal dele, e ao exército só com os botões do Rei. (/oly treasurer on|off)"
	L.CONSENT_TREASURER_EARLY = "Como Tesoureiro, o seu Sim também envia os nomes de todos que doaram antes da 1.0 (os primeiros apoiadores, do livro da 0.9): todo cliente no canal Olympus os recebe, os nomes também."
	L.CONSENT_TREASURER_OLD_YES = "O seu sim da 0.9.3 ainda envia o seu livro até você responder aqui."
	L.CONSENT_INSPECTION = "A Inspeção Real do Rei"
	L.CONSENT_INSPECTION_TEXT = "Quando o Rei, o Senescal dele ou uma Mão convoca uma e o seu addon cai na amostra, ele inspeciona os jogadores Olympus ao seu redor por 2 minutos e depois sussurra só para quem convocou: a sua guilda, quantos usavam o tabardo da guilda, outro ou nenhum, e até 6 nomes de quem foi pego sem as cores. O aviso de raide chega de qualquer jeito. (/oly inspection on|off)"
	L.CONSENT_ROLLCALL = "A chamada do autor"
	L.CONSENT_ROLLCALL_TEXT = "Quando o autor do addon pergunta, o seu addon sussurra só para ele a versão, o cliente do jogo, e se entrou no canal, se é o repórter da sua guilda e se o canal está selado. Nada sobre o seu personagem. Os avisos de atualização dele aparecem, a menos que você diga Não. (/oly rollcall on|off)"
	L.CONSENT_CHAT = "Os chats Olympus"
	L.CONSENT_CHAT_TEXT = "[Olympus], [Captains] e [Lords] (/ol, /olc, /oll), e a linha fixada. Sim: as linhas dos outros jogadores aparecem aqui, e você pode escrever; cada linha que você escreve chega a todos no canal Olympus. Não: este cliente não manda nem mostra esses chats. (/oly chat on|off)"
	L.CONSENT_TABARD_SELF_V2 = "Relatório do seu próprio tabardo"
	L.CONSENT_TABARD_SELF_V2_TEXT = "A identidade do seu personagem carimbada pelo servidor, guilda Olympus, nível e resultado atual do tabardo (da guilda, outro, nenhum, isento abaixo do nível 15 ou incompleto) são sussurrados somente para o cliente exato do Rei autenticado nos últimos 10 minutos. No máximo a cada 10 minutos e quando o tabardo muda. A evidência bruta fica por até 24 horas. Não mantém desligado; mudar para Não cancela todo relatório na fila antes da entrega. Um novo contrato de dados pergunta de novo."
	L.CONSENT_TABARD_NEARBY_V2 = "Observações diretas de tabardos próximos"
	L.CONSENT_TABARD_NEARBY_V2_TEXT = "Somente depois de uma inspeção que o seu cliente já concluiu, ele pode sussurrar para o cliente exato do Rei autenticado nos últimos 10 minutos: nome, guilda Olympus, nível e resultado do tabardo daquela pessoa, além da sua identidade carimbada pelo servidor como observador. O cliente do Rei registra quando recebeu. Nunca inicia uma segunda inspeção, repassa relato de outra pessoa nem transmite o nome observado nos canais da guilda ou Olympus. No máximo um resultado da mesma pessoa por minuto; a evidência bruta fica por até 24 horas. Não cancela tudo que estiver na fila antes da entrega. Um novo contrato de dados pergunta de novo."
	L.UNTABARDED_PUBLISHED_EMPTY = "Publicado pelo Rei: nenhuma entrada"
	L.VIEW_AS_TITLE = "Ver como"
	L.VIEW_AS_TIP = "Prévia local do autor. Minha visão: todas as abas, cada uma com o que o seu próprio personagem pode ver. Um papel: as abas e seções que esse papel vê, marcadas como prévia. Nunca muda a sua patente, a sua autoridade, os dados que você recebeu nem o que um clique pode enviar."
	L.VIEW_AS_MY = "Minha visão"
	L.VIEW_AS_KING = "Rei"
	L.VIEW_AS_TREASURER = "Tesoureiro"
	L.VIEW_AS_COUNCILLOR = "Alto Conselho"
