	L.NETOFF_YOU = "Os moderadores esconderam você para todo mundo com o addon (motivo: %s; por %s, %s): as suas falas nos chats do Olympus e a sua linha fixada, os decretos, as camadas e saltos, a Vox, os pedidos na corte, as entradas e inscrições na semana do Rei, as bandeiras e acampamentos no Mural, o seu anúncio no quadro de artesãos, e a sua borda de elite e marca na placa de identificação. O chat da Blizzard e a sua guilda não são tocados. Fale com um moderador se achar que foi um engano."
